"use client"

// Whole-file text viewer for source linking. It loads bounded text up front so
// every line is addressable, then virtualizes fixed-height rows for scrolling.
import * as React from "react"
import { useVirtualizer } from "@tanstack/react-virtual"

import { cn } from "@/lib/utils"
import {
  createViewerResource,
  type ViewerResource,
} from "@/lib/viewer-resource"
import type {
  BlobViewerSource,
  TextSource,
  UrlViewerSource,
} from "@/lib/viewer-source"
import { ScrollArea } from "@/components/ui/scroll-area"
import {
  TextViewerFallback,
  TextViewerFrame,
  TextViewerToolbar,
} from "@/components/ui/text-viewer-chrome"
import { scrollLineRangeMetricsIntoView } from "@/components/ui/text-viewer-layout"
import {
  isLineInRange,
  normalizeTextLineRange,
  type TextLineRange,
} from "@/components/ui/text-viewer-ranges"
import {
  readTextResource,
  resolvedTextViewerBounds,
  splitTextLines,
  type TextViewerBounds,
} from "@/components/ui/text-viewer-resource"
import { ViewerErrorBoundary } from "@/components/ui/viewer-error"

const BASE_FONT_PX = 12
const BASE_LINE_PX = 20
const MIN_SCALE = 0.25
const MAX_SCALE = 5
const TEXT_VIEWER_OVERSCAN = 24
const TEXT_VIEWER_BLOCK_PADDING = 8
const TEXT_VIEWER_INITIAL_VIEWPORT_HEIGHT = 600

const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value))

export type { TextLineRange }

interface TextVirtualLine {
  index: number
  key: React.Key
  size: number
  start: number
}

export interface TextViewerHandle {
  scrollToLineRange: (range: TextLineRange, options?: ScrollToOptions) => void
  getViewportElement: () => HTMLDivElement | null
}

export type TextDocumentSource = UrlViewerSource | BlobViewerSource | TextSource

export interface TextViewerProps extends TextViewerBounds {
  source: TextDocumentSource
  className?: string
  toolbar?: boolean
  /** 1-based inclusive line range to highlight, or null. */
  highlight?: TextLineRange | null
  /** Drop the outer border/rounded/background so the viewer fills its container. */
  bare?: boolean
}

export const TextViewer = React.forwardRef<TextViewerHandle, TextViewerProps>(
  function TextViewer(props, ref) {
    const [retryVersion, setRetryVersion] = React.useState(0)
    const isClient = useIsClient()
    const { source } = props
    const resource = React.useMemo(() => createViewerResource(source), [source])
    const resetKey = textViewerResetKey(resource, props, retryVersion)

    if (source.kind !== "text" && !isClient) {
      return (
        <TextViewerFallback
          className={props.className}
          toolbar={props.toolbar}
          bare={props.bare}
        />
      )
    }

    return (
      <ViewerErrorBoundary
        bare={props.bare}
        className={props.className}
        download={resource.getOriginalDownload()}
        format="text"
        resetKey={resetKey}
        sourceKind={resource.sourceKind}
        onRetry={() => setRetryVersion((version) => version + 1)}
      >
        <React.Suspense
          fallback={
            <TextViewerFallback
              className={props.className}
              toolbar={props.toolbar}
              bare={props.bare}
            />
          }
        >
          <TextViewerInner
            {...props}
            forwardedRef={ref}
            retryVersion={retryVersion}
            resource={resource}
          />
        </React.Suspense>
      </ViewerErrorBoundary>
    )
  }
)

function TextViewerInner({
  resource,
  className,
  toolbar = true,
  highlight,
  bare = false,
  maxBytes,
  maxLines,
  retryVersion,
  forwardedRef,
}: TextViewerProps & {
  resource: ViewerResource
  retryVersion: number
  forwardedRef?: React.ForwardedRef<TextViewerHandle>
}) {
  const bounds = resolvedTextViewerBounds({ maxBytes, maxLines })
  const text = readTextResource({ resource, retryVersion, bounds })
  const textLines = React.useMemo(() => splitTextLines(text), [text])
  const highlightRange = normalizeTextLineRange(highlight, textLines.length)
  const downloadAction = React.useMemo(
    () => resource.getOriginalDownload(),
    [resource]
  )

  const [fontScale, setFontScale] = React.useState(1)
  const viewportElementRef = React.useRef<HTMLDivElement | null>(null)
  const lineHeight = BASE_LINE_PX * fontScale
  const lineVirtualizer = useVirtualizer({
    count: textLines.length,
    getScrollElement: () => viewportElementRef.current,
    estimateSize: () => lineHeight,
    overscan: TEXT_VIEWER_OVERSCAN,
    paddingStart: TEXT_VIEWER_BLOCK_PADDING,
    paddingEnd: TEXT_VIEWER_BLOCK_PADDING,
    initialRect: { width: 800, height: TEXT_VIEWER_INITIAL_VIEWPORT_HEIGHT },
  })

  const zoom = (factor: number) =>
    setFontScale((scale) => clamp(scale * factor, MIN_SCALE, MAX_SCALE))

  React.useEffect(() => {
    lineVirtualizer.measure()
  }, [lineHeight, lineVirtualizer])

  React.useImperativeHandle(
    forwardedRef,
    () => ({
      scrollToLineRange: (range, options) => {
        scrollLineRangeMetricsIntoView({
          viewportElement: viewportElementRef.current,
          range: normalizeTextLineRange(range, textLines.length),
          lineHeight,
          paddingStart: TEXT_VIEWER_BLOCK_PADDING,
          options,
        })
      },
      getViewportElement: () => viewportElementRef.current,
    }),
    [lineHeight, textLines.length]
  )

  const gutterWidth = `${String(textLines.length).length + 1}ch`
  const measuredVirtualLines = lineVirtualizer.getVirtualItems()
  const virtualLines =
    measuredVirtualLines.length > 0
      ? measuredVirtualLines
      : createInitialTextVirtualLines(textLines.length, lineHeight)

  return (
    <TextViewerFrame className={className} bare={bare}>
      {toolbar ? (
        <TextViewerToolbar
          lineCount={textLines.length}
          fontScale={fontScale}
          downloadAction={downloadAction}
          onZoomOut={() => zoom(1 / 1.2)}
          onZoomIn={() => zoom(1.2)}
          onResetZoom={() => setFontScale(1)}
        />
      ) : null}
      <ScrollArea className="min-h-0 flex-1" viewportRef={viewportElementRef}>
        <pre
          className="relative w-max min-w-full font-mono"
          style={{
            fontSize: `${BASE_FONT_PX * fontScale}px`,
            lineHeight: `${lineHeight}px`,
            height: lineVirtualizer.getTotalSize(),
          }}
        >
          {virtualLines.map((virtualLine) => {
            const lineNumber = virtualLine.index + 1
            return (
              <TextLine
                key={virtualLine.key}
                gutterWidth={gutterWidth}
                isHighlighted={isLineInRange(lineNumber, highlightRange)}
                lineNumber={lineNumber}
                text={textLines[virtualLine.index] ?? ""}
                style={{
                  height: virtualLine.size,
                  transform: `translateY(${virtualLine.start}px)`,
                }}
              />
            )
          })}
        </pre>
      </ScrollArea>
    </TextViewerFrame>
  )
}

function createInitialTextVirtualLines(
  lineCount: number,
  lineHeight: number
): TextVirtualLine[] {
  const windowLineCount = Math.min(
    lineCount,
    Math.ceil(TEXT_VIEWER_INITIAL_VIEWPORT_HEIGHT / lineHeight) +
      TEXT_VIEWER_OVERSCAN * 2
  )

  return Array.from({ length: windowLineCount }, (_, index) => ({
    index,
    key: index,
    size: lineHeight,
    start: TEXT_VIEWER_BLOCK_PADDING + index * lineHeight,
  }))
}

function TextLine({
  gutterWidth,
  isHighlighted,
  lineNumber,
  style,
  text,
}: {
  gutterWidth: string
  isHighlighted: boolean
  lineNumber: number
  style: React.CSSProperties
  text: string
}) {
  return (
    <div
      data-line-number={lineNumber}
      className={cn(
        "absolute top-0 left-0 flex min-w-full px-2",
        isHighlighted && "bg-primary/12 ring-1 ring-primary/30 ring-inset"
      )}
      style={style}
    >
      <span
        className="flex-shrink-0 pr-3 text-right text-muted-foreground/60 select-none"
        style={{ width: gutterWidth }}
      >
        {lineNumber}
      </span>
      <span className="whitespace-pre">{text || " "}</span>
    </div>
  )
}

function textViewerResetKey(
  resource: ViewerResource,
  props: Pick<TextViewerProps, "maxBytes" | "maxLines">,
  retryVersion: number
): string {
  return [
    resource.keys.resource,
    retryVersion,
    props.maxBytes ?? "",
    props.maxLines ?? "",
  ].join("\u0000")
}

function useIsClient() {
  return React.useSyncExternalStore(
    () => () => {},
    () => true,
    () => false
  )
}

"use client"

import * as React from "react"
import { Maximize, Minus, Plus, RotateCcw } from "lucide-react"

import { cn } from "@/lib/utils"
import { type ViewerDownloadAction } from "@/lib/viewer-download"
import { Button } from "@/components/ui/button"
import { Skeleton } from "@/components/ui/skeleton"
import { ViewerDownloadControl } from "@/components/ui/viewer-download"

export function TextViewerFrame({
  className,
  bare,
  children,
}: {
  className?: string
  bare?: boolean
  children: React.ReactNode
}) {
  return (
    <div
      className={cn(
        "flex min-h-0 flex-col overflow-hidden",
        bare ? "h-full bg-muted/20" : "rounded-xl border bg-muted/30",
        className
      )}
      data-slot="text-viewer"
    >
      {children}
    </div>
  )
}

export function TextViewerToolbar({
  lineCount,
  fontScale,
  downloadAction,
  onZoomOut,
  onZoomIn,
  onResetZoom,
}: {
  lineCount: number
  fontScale: number
  downloadAction: ViewerDownloadAction
  onZoomOut: () => void
  onZoomIn: () => void
  onResetZoom: () => void
}) {
  return (
    <TextViewerToolbarFrame
      leading={`${lineCount} line${lineCount === 1 ? "" : "s"}`}
      trailing={
        <>
          <TextViewerZoomControls
            fontScale={fontScale}
            onZoomOut={onZoomOut}
            onZoomIn={onZoomIn}
            onResetZoom={onResetZoom}
          />
          <div className="mx-1 h-4 w-px bg-border" />
          <ViewerDownloadControl actions={[downloadAction]} />
        </>
      }
    />
  )
}

export function TextViewerFallback({
  className,
  toolbar = true,
  bare,
}: {
  className?: string
  toolbar?: boolean
  bare?: boolean
}) {
  return (
    <TextViewerFrame className={className} bare={bare}>
      {toolbar ? (
        <TextViewerToolbarFrame
          leading={<Skeleton className="inline-block h-3 w-16 align-middle" />}
          trailing={<TextViewerZoomControls disabled fontScale={1} />}
        />
      ) : null}
      <div className="space-y-2 p-4">
        {Array.from({ length: 12 }, (_, index) => (
          <Skeleton
            key={index}
            className="h-4"
            style={{ width: `${40 + ((index * 13) % 55)}%` }}
          />
        ))}
      </div>
    </TextViewerFrame>
  )
}

export function TextViewerErrorState({
  className,
  bare,
  message,
  isRetryable,
  downloadAction,
  onRetry,
}: {
  className?: string
  bare?: boolean
  message: string
  isRetryable: boolean
  downloadAction: ViewerDownloadAction
  onRetry: () => void
}) {
  return (
    <TextViewerFrame className={className} bare={bare}>
      <div className="flex min-h-64 flex-1 flex-col items-center justify-center gap-3 p-6 text-center text-sm text-muted-foreground">
        <p>{message}</p>
        <div className="flex items-center gap-2">
          {isRetryable ? (
            <Button variant="outline" size="sm" onClick={onRetry}>
              <RotateCcw className="mr-1.5 size-4" />
              Retry
            </Button>
          ) : null}
          <ViewerDownloadControl
            actions={[downloadAction]}
            variant={message.includes("too large") ? "outline" : "ghost"}
            size="sm"
            className=""
            showLabel
          />
        </div>
      </div>
    </TextViewerFrame>
  )
}

function TextViewerToolbarFrame({
  leading,
  trailing,
}: {
  leading: React.ReactNode
  trailing: React.ReactNode
}) {
  return (
    <div className="flex h-10 flex-shrink-0 items-center gap-1 border-b bg-card px-2">
      <span className="px-1 text-xs text-muted-foreground tabular-nums">
        {leading}
      </span>
      <div className="ml-auto flex items-center gap-1">{trailing}</div>
    </div>
  )
}

function TextViewerZoomControls({
  fontScale,
  disabled = false,
  onZoomOut,
  onZoomIn,
  onResetZoom,
}: {
  fontScale: number
  disabled?: boolean
  onZoomOut?: () => void
  onZoomIn?: () => void
  onResetZoom?: () => void
}) {
  const disabledProps = disabled
    ? ({ disabled: true, tabIndex: -1, "aria-hidden": true } as const)
    : {}

  return (
    <>
      <IconButton
        label="Zoom out"
        onClick={disabled ? undefined : onZoomOut}
        {...disabledProps}
      >
        <Minus />
      </IconButton>
      <span className="w-12 text-center text-xs text-muted-foreground tabular-nums">
        {Math.round(fontScale * 100)}%
      </span>
      <IconButton
        label="Zoom in"
        onClick={disabled ? undefined : onZoomIn}
        {...disabledProps}
      >
        <Plus />
      </IconButton>
      <IconButton
        label="Reset zoom"
        onClick={disabled ? undefined : onResetZoom}
        {...disabledProps}
      >
        <Maximize />
      </IconButton>
    </>
  )
}

function IconButton({
  label,
  children,
  ...props
}: React.ComponentProps<typeof Button> & { label: string }) {
  return (
    <Button
      variant="ghost"
      size="icon-sm"
      className="size-7"
      aria-label={label}
      title={label}
      {...props}
    >
      {children}
    </Button>
  )
}

"use client"

import * as React from "react"
import { Download } from "lucide-react"

import { cn } from "@/lib/utils"
import {
  ViewerDownloadError,
  type ViewerDownloadAction,
  type ViewerDownloadPayload,
} from "@/lib/viewer-download"
import { Button, buttonVariants } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"

export async function triggerViewerDownload(
  action: ViewerDownloadAction,
  options?: { signal?: AbortSignal }
): Promise<void> {
  if (action.isDisabled) {
    throw new ViewerDownloadError({
      actionId: action.id,
      kind: "disabled",
      message: "This download is disabled.",
    })
  }

  let payload: ViewerDownloadPayload
  try {
    payload = await action.getPayload(options)
  } catch (error) {
    if (isAbortError(error)) {
      throw new ViewerDownloadError({
        actionId: action.id,
        kind: "aborted",
        message: "Download was cancelled.",
        cause: error,
      })
    }
    throw new ViewerDownloadError({
      actionId: action.id,
      kind: "payload_failed",
      message: "Could not prepare this download.",
      cause: error,
    })
  }

  if (payload.kind === "none") return
  if (payload.kind === "href") {
    clickDownload(payload.href, action.fileName)
    return
  }

  const blob =
    payload.kind === "blob"
      ? payload.blob
      : new Blob([payload.text], {
          type: payload.mimeType ?? "text/plain;charset=utf-8",
        })
  const url = URL.createObjectURL(blob)
  try {
    clickDownload(url, action.fileName)
  } finally {
    URL.revokeObjectURL(url)
  }
}

type ViewerDownloadErrorHandler = (
  error: ViewerDownloadError,
  action: ViewerDownloadAction
) => void

export function useViewerDownloadHref(
  action: ViewerDownloadAction | null
): string | null {
  const shouldCreateHref = action?.origin !== "derived"
  const payload = shouldCreateHref ? getSynchronousPayload(action) : null

  return shouldCreateHref && payload?.kind === "href" ? payload.href : null
}

export function ViewerDownloadControl({
  actions,
  variant = "ghost",
  size = "icon-sm",
  className = "size-7",
  showLabel = false,
  onError,
}: {
  actions: Array<ViewerDownloadAction | null | undefined>
  variant?: React.ComponentProps<typeof Button>["variant"]
  size?: React.ComponentProps<typeof Button>["size"]
  className?: string
  showLabel?: boolean
  onError?: ViewerDownloadErrorHandler
}) {
  const enabledActions = actions.filter(
    (action): action is ViewerDownloadAction => Boolean(action)
  )

  if (enabledActions.length <= 1) {
    return (
      <ViewerDownloadButton
        action={enabledActions[0] ?? null}
        variant={variant}
        size={size}
        className={className}
        showLabel={showLabel}
        onError={onError}
      />
    )
  }

  return (
    <ViewerDownloadMenu
      actions={enabledActions}
      variant={variant}
      size={size}
      className={className}
      showLabel={showLabel}
      onError={onError}
    />
  )
}

export function ViewerDownloadButton({
  action,
  variant = "ghost",
  size = "icon-sm",
  className = "size-7",
  showLabel = false,
  onError,
}: {
  action: ViewerDownloadAction | null
  variant?: React.ComponentProps<typeof Button>["variant"]
  size?: React.ComponentProps<typeof Button>["size"]
  className?: string
  showLabel?: boolean
  onError?: ViewerDownloadErrorHandler
}) {
  const [isPending, setIsPending] = React.useState(false)
  const abortControllerRef = React.useRef<AbortController | null>(null)
  const href = useViewerDownloadHref(action)
  const label = action?.label ?? "Download"
  const disabled = !action || action.isDisabled
  const hasDownloadHref = Boolean(href)

  React.useEffect(() => {
    return () => {
      abortControllerRef.current?.abort()
      abortControllerRef.current = null
    }
  }, [action])

  const handleClick = React.useCallback(() => {
    if (!action || hasDownloadHref) return
    abortControllerRef.current?.abort()
    const abortController = new AbortController()
    abortControllerRef.current = abortController
    setIsPending(true)
    void triggerViewerDownload(action, { signal: abortController.signal })
      .catch((error) => {
        reportDownloadError(error, action, onError)
      })
      .finally(() => {
        if (abortControllerRef.current === abortController) {
          abortControllerRef.current = null
          setIsPending(false)
        }
      })
  }, [action, hasDownloadHref, onError])

  if (href) {
    return (
      <a
        href={href}
        download={action?.fileName}
        className={cn(buttonVariants({ variant, size }), className)}
        aria-label={label}
        title={label}
        data-slot="button"
      >
        <Download className={showLabel ? "mr-1.5 size-4" : undefined} />
        {showLabel ? label : null}
      </a>
    )
  }

  return (
    <Button
      variant={variant}
      size={size}
      className={className}
      aria-label={label}
      title={label}
      disabled={disabled}
      loading={isPending}
      onClick={handleClick}
    >
      <Download className={showLabel ? "mr-1.5 size-4" : undefined} />
      {showLabel ? label : null}
    </Button>
  )
}

export function ViewerDownloadMenu({
  actions,
  variant = "ghost",
  size = "icon-sm",
  className = "size-7",
  showLabel = false,
  onError,
}: {
  actions: ViewerDownloadAction[]
  variant?: React.ComponentProps<typeof Button>["variant"]
  size?: React.ComponentProps<typeof Button>["size"]
  className?: string
  showLabel?: boolean
  onError?: ViewerDownloadErrorHandler
}) {
  const [pendingActionId, setPendingActionId] = React.useState<string | null>(
    null
  )
  const abortControllerRef = React.useRef<AbortController | null>(null)
  const actionSetKey = actions.map((action) => action.id).join("\u0000")
  const label = "Download"

  React.useEffect(() => {
    return () => {
      abortControllerRef.current?.abort()
      abortControllerRef.current = null
    }
  }, [actionSetKey])

  const trigger = (action: ViewerDownloadAction) => {
    abortControllerRef.current?.abort()
    const abortController = new AbortController()
    abortControllerRef.current = abortController
    setPendingActionId(action.id)
    void triggerViewerDownload(action, { signal: abortController.signal })
      .catch((error) => {
        reportDownloadError(error, action, onError)
      })
      .finally(() => {
        if (abortControllerRef.current === abortController) {
          abortControllerRef.current = null
          setPendingActionId(null)
        }
      })
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button
            variant={variant}
            size={size}
            className={className}
            aria-label={label}
            title={label}
            loading={pendingActionId != null}
          >
            <Download className={showLabel ? "mr-1.5 size-4" : undefined} />
            {showLabel ? label : null}
          </Button>
        }
      />
      <DropdownMenuContent align="end">
        {actions.map((action) => (
          <DropdownMenuItem
            key={action.id}
            disabled={action.isDisabled || pendingActionId != null}
            onClick={() => trigger(action)}
          >
            <Download />
            <span>{action.label}</span>
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

function clickDownload(href: string, fileName: string) {
  const anchor = document.createElement("a")
  anchor.href = href
  anchor.download = fileName
  anchor.rel = "noreferrer"
  document.body.appendChild(anchor)
  anchor.click()
  anchor.remove()
}

function getSynchronousPayload(
  action: ViewerDownloadAction | null
): ViewerDownloadPayload | null {
  if (!action || action.isDisabled) return null
  const payload = action.getPayload()
  return payload instanceof Promise ? null : payload
}

function reportDownloadError(
  error: unknown,
  action: ViewerDownloadAction,
  onError: ViewerDownloadErrorHandler | undefined
) {
  if (!(error instanceof ViewerDownloadError)) return
  if (error.kind === "aborted") return
  onError?.(error, action)
}

function isAbortError(error: unknown) {
  return error instanceof DOMException && error.name === "AbortError"
}

export interface TextLineRange {
  start: number
  end: number
}

export interface NormalizedTextLineRange extends TextLineRange {
  readonly normalized: true
}

const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value))

export function normalizeTextLineRange(
  range: TextLineRange | null | undefined,
  lineCount: number
): NormalizedTextLineRange | null {
  if (
    !range ||
    !Number.isFinite(range.start) ||
    !Number.isFinite(range.end) ||
    !Number.isFinite(lineCount) ||
    lineCount <= 0
  ) {
    return null
  }

  const maxLine = Math.floor(lineCount)
  const rawStart = Math.trunc(range.start)
  const rawEnd = Math.trunc(range.end)
  const start = Math.min(rawStart, rawEnd)
  const end = Math.max(rawStart, rawEnd)

  if (end < 1 || start > maxLine) return null

  return {
    start: clamp(start, 1, maxLine),
    end: clamp(end, 1, maxLine),
    normalized: true,
  }
}

export function isLineInRange(
  lineNumber: number,
  range: NormalizedTextLineRange | null
) {
  return range != null && lineNumber >= range.start && lineNumber <= range.end
}

import { ResourceError, ViewerFormatError } from "@/lib/viewer-errors"
import { type ViewerResource } from "@/lib/viewer-resource"

export const DEFAULT_MAX_BYTES = 1_000_000
export const DEFAULT_MAX_LINES = 10_000
export const MAX_TEXT_RESOURCE_CACHE_ENTRIES = 64

export interface TextViewerBounds {
  maxBytes?: number
  maxLines?: number
}

export type TextViewerTooLargeReason = "bytes" | "lines"
export type TextViewerBoundName = "maxBytes" | "maxLines"

export class TextViewerTooLargeError extends ViewerFormatError {
  readonly reason: TextViewerTooLargeReason

  constructor(reason: TextViewerTooLargeReason) {
    super({
      format: "text",
      kind: "bounds",
      message: `Text file exceeds ${reason} limit`,
    })
    this.name = "TextViewerTooLargeError"
    this.reason = reason
  }
}

export class TextViewerInvalidBoundsError extends ViewerFormatError {
  readonly boundName: TextViewerBoundName

  constructor(boundName: TextViewerBoundName) {
    super({
      format: "text",
      kind: "bounds",
      message: `${boundName} must be a positive integer`,
    })
    this.name = "TextViewerInvalidBoundsError"
    this.boundName = boundName
  }
}

interface TextResource {
  promise: Promise<string>
  status: "pending" | "fulfilled" | "rejected"
  value?: string
  error?: unknown
}

const textResourceCache = new Map<string, TextResource>()

function textViewerResourceKey({
  resource,
  retryVersion,
  bounds,
}: {
  resource: ViewerResource
  retryVersion: number
  bounds: Required<TextViewerBounds>
}) {
  return `${resource.keys.load}\0${retryVersion}\0${bounds.maxBytes}\0${bounds.maxLines}`
}

export function clearTextViewerResourceCacheForTests() {
  textResourceCache.clear()
}

export function resolvedTextViewerBounds({
  maxBytes = DEFAULT_MAX_BYTES,
  maxLines = DEFAULT_MAX_LINES,
}: TextViewerBounds = {}): Required<TextViewerBounds> {
  return {
    maxBytes: resolveTextViewerBound(maxBytes, "maxBytes"),
    maxLines: resolveTextViewerBound(maxLines, "maxLines"),
  }
}

export function assertTextWithinBounds(
  text: string,
  bounds: Required<TextViewerBounds>
) {
  if (new TextEncoder().encode(text).byteLength > bounds.maxBytes) {
    throw new TextViewerTooLargeError("bytes")
  }
  if (lineCountOf(text) > bounds.maxLines) {
    throw new TextViewerTooLargeError("lines")
  }
}

export function splitTextLines(text: string) {
  return text.split(/\r\n|\n|\r/g)
}

export function readTextResource({
  resource,
  retryVersion,
  bounds,
}: {
  resource: ViewerResource
  retryVersion: number
  bounds: Required<TextViewerBounds>
}) {
  const inlineText = resource.getInlineText()
  if (inlineText !== null) {
    assertTextWithinBounds(inlineText, bounds)
    return inlineText
  }

  const resourceKey = textViewerResourceKey({ resource, retryVersion, bounds })
  const textResource = getTextResource({ resource, resourceKey, bounds })

  if (textResource.status === "fulfilled") return textResource.value ?? ""
  if (textResource.status === "rejected") throw textResource.error

  throw textResource.promise
}

function getTextResource({
  resource,
  resourceKey,
  bounds,
}: {
  resource: ViewerResource
  resourceKey: string
  bounds: Required<TextViewerBounds>
}) {
  let textResource = textResourceCache.get(resourceKey)
  if (!textResource) {
    const nextResource: TextResource = {
      status: "pending",
      promise: readBoundedTextResource(resource, bounds),
    }
    nextResource.promise.then(
      (value) => {
        nextResource.status = "fulfilled"
        nextResource.value = value
      },
      (error) => {
        nextResource.status = "rejected"
        nextResource.error = error
      }
    )
    textResource = nextResource
    textResourceCache.set(resourceKey, textResource)
    trimTextResourceCache()
  }
  return textResource
}

async function readBoundedTextResource(
  resource: ViewerResource,
  bounds: Required<TextViewerBounds>
) {
  try {
    return await resource.readText(bounds)
  } catch (error) {
    if (error instanceof ResourceError && error.kind === "too_large") {
      throw new TextViewerTooLargeError(error.tooLargeReason ?? "bytes")
    }
    throw error
  }
}

function lineCountOf(text: string) {
  return splitTextLines(text).length
}

function resolveTextViewerBound(value: number, boundName: TextViewerBoundName) {
  if (!Number.isSafeInteger(value) || value < 1) {
    throw new TextViewerInvalidBoundsError(boundName)
  }
  return value
}

function trimTextResourceCache() {
  while (textResourceCache.size > MAX_TEXT_RESOURCE_CACHE_ENTRIES) {
    const firstKey = textResourceCache.keys().next().value
    if (firstKey === undefined) return
    textResourceCache.delete(firstKey)
  }
}

import type { NormalizedTextLineRange } from "@/components/ui/text-viewer-ranges"

export const LINE_SCROLL_HEADROOM = 64

export interface LineRangeRects {
  startTop: number
  endBottom: number
  viewportTop: number
  viewportScrollTop: number
  viewportHeight: number
}

export interface LineRangeMetrics {
  startLine: number
  endLine: number
  lineHeight: number
  viewportHeight: number
  paddingStart?: number
}

export function findLineElement(
  viewportElement: HTMLElement,
  lineNumber: number
): HTMLElement | null {
  if (!Number.isInteger(lineNumber) || lineNumber < 1) return null
  return viewportElement.querySelector<HTMLElement>(
    `[data-line-number="${lineNumber}"]`
  )
}

export function scrollTopForLineRange({
  startTop,
  endBottom,
  viewportTop,
  viewportScrollTop,
  viewportHeight,
}: LineRangeRects) {
  const rangeTop = startTop - viewportTop + viewportScrollTop
  const rangeBottom = endBottom - viewportTop + viewportScrollTop
  const rangeHeight = rangeBottom - rangeTop
  const targetTop =
    rangeHeight <= viewportHeight
      ? rangeTop - (viewportHeight - rangeHeight) / 2
      : rangeTop - LINE_SCROLL_HEADROOM

  return Math.max(0, targetTop)
}

export function scrollTopForLineRangeMetrics({
  startLine,
  endLine,
  lineHeight,
  viewportHeight,
  paddingStart = 0,
}: LineRangeMetrics) {
  const rangeTop = paddingStart + (startLine - 1) * lineHeight
  const rangeBottom = paddingStart + endLine * lineHeight
  const rangeHeight = rangeBottom - rangeTop
  const targetTop =
    rangeHeight <= viewportHeight
      ? rangeTop - (viewportHeight - rangeHeight) / 2
      : rangeTop - LINE_SCROLL_HEADROOM

  return Math.max(0, targetTop)
}

export function scrollLineRangeIntoView({
  viewportElement,
  range,
  options,
}: {
  viewportElement: HTMLDivElement | null
  range: NormalizedTextLineRange | null
  options?: ScrollToOptions
}) {
  if (!viewportElement || !range) return

  const startLineElement = findLineElement(viewportElement, range.start)
  const endLineElement = findLineElement(viewportElement, range.end)
  if (!startLineElement || !endLineElement) return

  const startLineRect = startLineElement.getBoundingClientRect()
  const endLineRect = endLineElement.getBoundingClientRect()
  const viewportRect = viewportElement.getBoundingClientRect()

  viewportElement.scrollTo({
    top: scrollTopForLineRange({
      startTop: startLineRect.top,
      endBottom: endLineRect.bottom,
      viewportTop: viewportRect.top,
      viewportScrollTop: viewportElement.scrollTop,
      viewportHeight: viewportElement.clientHeight,
    }),
    behavior: "smooth",
    ...options,
  })
}

export function scrollLineRangeMetricsIntoView({
  viewportElement,
  range,
  lineHeight,
  paddingStart,
  options,
}: {
  viewportElement: HTMLDivElement | null
  range: NormalizedTextLineRange | null
  lineHeight: number
  paddingStart?: number
  options?: ScrollToOptions
}) {
  if (!viewportElement || !range) return

  viewportElement.scrollTo({
    top: scrollTopForLineRangeMetrics({
      startLine: range.start,
      endLine: range.end,
      lineHeight,
      paddingStart,
      viewportHeight: viewportElement.clientHeight,
    }),
    behavior: "smooth",
    ...options,
  })
}

import {
  createBlobDownloadAction,
  createHrefDownloadAction,
  createTextDownloadAction,
  type ViewerDownloadAction,
} from "@/lib/viewer-download"
import {
  isAbortError,
  ResourceError,
  type ResourceTooLargeReason,
} from "@/lib/viewer-errors"
import {
  resolveViewerDescriptor,
  type BlobViewerSource,
  type TextSource,
  type UrlViewerSource,
  type ViewerDescriptor,
  type ViewerSource,
} from "@/lib/viewer-source"

export interface ResourceReadOptions {
  signal?: AbortSignal
}

export interface TextReadOptions extends ResourceReadOptions {
  maxBytes?: number
  maxLines?: number
}

export interface ByteRange {
  start: number
  end: number
}

export interface ByteRangeResult {
  buffer: ArrayBuffer
  contentRange?: {
    start: number
    end: number
    total: number | null
  }
  isComplete: boolean
}

export type DirectLoadCapability =
  | { kind: "url"; url: string }
  | { kind: "none" }

export interface ViewerResourceKeys {
  readonly load: string
  readonly presentation: string
  readonly resource: string
}

export interface ViewerResource {
  readonly descriptor: ViewerDescriptor
  readonly sourceKind: ViewerSource["kind"]
  readonly keys: ViewerResourceKeys
  readonly identityKey: string
  readonly fileName: string
  readonly mimeType?: string

  getDirectLoad(): DirectLoadCapability
  getOriginalDownload(): ViewerDownloadAction
  getInlineText(): string | null
  getBlob(): Blob | null
  readBlob(options?: ResourceReadOptions): Promise<Blob>
  readArrayBuffer(options?: ResourceReadOptions): Promise<ArrayBuffer>
  readText(options?: TextReadOptions): Promise<string>
  stream(options?: ResourceReadOptions): Promise<ReadableStream<Uint8Array>>
  readRange(
    range: ByteRange,
    options?: ResourceReadOptions
  ): Promise<ByteRangeResult>
}

const URL_RESOURCE_REGISTRY_MAX = 128
const TEXT_LINE_BREAK_PATTERN = /\r\n|\n|\r/g

const urlViewerResourceRegistry = new Map<string, ViewerResource>()
let blobViewerResourceRegistry = new WeakMap<
  Blob,
  Map<string, ViewerResource>
>()
const blobObjectKeys = new WeakMap<Blob, string>()
let nextBlobObjectKey = 0

export function createViewerResource(source: ViewerSource): ViewerResource {
  const descriptor = resolveViewerDescriptor({ source })
  const keys = viewerResourceKeys(source, descriptor)

  if (source.kind === "url") {
    return internUrlResource(source, descriptor, keys)
  }
  if (source.kind === "blob") {
    return internBlobResource(source, descriptor, keys)
  }
  return createUncachedViewerResource(source, descriptor, keys)
}

export function clearViewerResourceRegistryForTests() {
  urlViewerResourceRegistry.clear()
  blobViewerResourceRegistry = new WeakMap()
}

function createUncachedViewerResource(
  source: ViewerSource,
  descriptor: ViewerDescriptor,
  keys: ViewerResourceKeys
): ViewerResource {
  switch (source.kind) {
    case "url":
      return createUrlResource(source, descriptor, keys)
    case "blob":
      return createBlobResource(source, descriptor, keys)
    case "text":
      return createTextResource(source, descriptor, keys)
  }
}

function internUrlResource(
  source: UrlViewerSource,
  descriptor: ViewerDescriptor,
  keys: ViewerResourceKeys
): ViewerResource {
  const cached = urlViewerResourceRegistry.get(keys.resource)
  if (cached) return cached

  const resource = createUrlResource(source, descriptor, keys)
  urlViewerResourceRegistry.set(keys.resource, resource)
  pruneUrlResourceRegistry()
  return resource
}

function internBlobResource(
  source: BlobViewerSource,
  descriptor: ViewerDescriptor,
  keys: ViewerResourceKeys
): ViewerResource {
  let resources = blobViewerResourceRegistry.get(source.blob)
  if (!resources) {
    resources = new Map()
    blobViewerResourceRegistry.set(source.blob, resources)
  }

  const cached = resources.get(keys.resource)
  if (cached) return cached

  const resource = createBlobResource(source, descriptor, keys)
  resources.set(keys.resource, resource)
  return resource
}

function pruneUrlResourceRegistry() {
  while (urlViewerResourceRegistry.size > URL_RESOURCE_REGISTRY_MAX) {
    const firstKey = urlViewerResourceRegistry.keys().next().value
    if (!firstKey) return
    urlViewerResourceRegistry.delete(firstKey)
  }
}

function viewerResourceKeys(
  source: ViewerSource,
  descriptor: ViewerDescriptor
): ViewerResourceKeys {
  const load = viewerResourceLoadKey(source)
  const presentation = viewerResourcePresentationKey(source, descriptor)
  return {
    load,
    presentation,
    resource: [load, presentation].join("\u0000"),
  }
}

function viewerResourceLoadKey(source: ViewerSource) {
  return [
    source.kind,
    source.identityKey ?? "",
    directLoadCacheKey(source),
    payloadCacheKey(source),
  ].join("\u0000")
}

function viewerResourcePresentationKey(
  source: ViewerSource,
  descriptor: ViewerDescriptor
) {
  return [
    descriptor.category,
    descriptor.displayName,
    descriptor.fileName,
    descriptor.mimeType ?? "",
    downloadCacheKey(source),
  ].join("\u0000")
}

function directLoadCacheKey(source: ViewerSource) {
  return source.kind === "url" ? source.url : ""
}

function downloadCacheKey(source: ViewerSource) {
  if (source.kind === "text") return ""
  return source.downloadUrl ?? ""
}

function payloadCacheKey(source: ViewerSource) {
  if (source.kind === "url") return ""
  if (source.kind === "blob") return blobObjectKey(source.blob)
  return `text:${source.text.length}:${hashString(source.text)}`
}

function blobObjectKey(blob: Blob) {
  let key = blobObjectKeys.get(blob)
  if (!key) {
    nextBlobObjectKey += 1
    key = `blob-object:${nextBlobObjectKey}`
    blobObjectKeys.set(blob, key)
  }
  return key
}

function hashString(text: string) {
  let hash = 0x811c9dc5
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index)
    hash = Math.imul(hash, 0x01000193)
  }
  return (hash >>> 0).toString(36)
}

export function blobSource(
  bytes: Blob | ArrayBuffer | Uint8Array,
  metadata: {
    identityKey: string
    fileName?: string
    mimeType?: string
    downloadUrl?: string
  }
): BlobViewerSource {
  const blob =
    bytes instanceof Blob
      ? bytes
      : new Blob(
          [bytes instanceof ArrayBuffer ? bytes : new Uint8Array(bytes)],
          {
            type: metadata.mimeType ?? "",
          }
        )
  return {
    kind: "blob",
    blob,
    fileName: metadata.fileName,
    mimeType: metadata.mimeType ?? blob.type,
    downloadUrl: metadata.downloadUrl,
    identityKey: metadata.identityKey,
  }
}

function createUrlResource(
  source: UrlViewerSource,
  descriptor: ViewerDescriptor,
  keys: ViewerResourceKeys
): ViewerResource {
  return resourceBase(source, descriptor, keys, {
    getDirectLoad: () => ({ kind: "url", url: source.url }),
    getOriginalDownload: () =>
      createHrefDownloadAction({
        id: "download-original",
        label: "Download",
        href: source.downloadUrl ?? source.url,
        fileName: descriptor.fileName,
      }),
    getInlineText: () => null,
    getBlob: () => null,
    readBlob: async ({ signal } = {}) => {
      const response = await fetchResource(source.url, { signal })
      return response.blob()
    },
    readArrayBuffer: async ({ signal } = {}) => {
      const response = await fetchResource(source.url, { signal })
      return response.arrayBuffer()
    },
    readText: async ({ signal, maxBytes, maxLines } = {}) => {
      const response = await fetchResource(source.url, { signal })
      return readBoundedResponseText(response, { maxBytes, maxLines })
    },
    stream: async ({ signal } = {}) => {
      const response = await fetchResource(source.url, { signal })
      if (!response.body) {
        throw new ResourceError({
          kind: "unsupported_capability",
          message: "This response cannot be streamed.",
        })
      }
      return response.body
    },
    readRange: async (range, { signal } = {}) => {
      validateByteRange(range)
      const { start, end } = range
      const response = await fetchResource(source.url, {
        signal,
        headers: { Range: `bytes=${start}-${end}` },
      })
      const buffer = await response.arrayBuffer()
      const contentRange = parseContentRange(
        response.headers.get("content-range")
      )
      return {
        buffer,
        contentRange,
        isComplete: isByteRangeComplete({
          bufferLength: buffer.byteLength,
          contentRange,
          requestedLength: end - start + 1,
          status: response.status,
        }),
      }
    },
  })
}

function createBlobResource(
  source: BlobViewerSource,
  descriptor: ViewerDescriptor,
  keys: ViewerResourceKeys
): ViewerResource {
  const blob = source.blob
  return resourceBase(source, descriptor, keys, {
    getDirectLoad: () => ({ kind: "none" }),
    getOriginalDownload: () =>
      source.downloadUrl
        ? createHrefDownloadAction({
            id: "download-original",
            label: "Download",
            href: source.downloadUrl,
            fileName: descriptor.fileName,
          })
        : createBlobDownloadAction({
            id: "download-original",
            label: "Download",
            blob,
            fileName: descriptor.fileName,
          }),
    getInlineText: () => null,
    getBlob: () => blob,
    readBlob: async () => blob,
    readArrayBuffer: async () => blob.arrayBuffer(),
    readText: async ({ maxBytes, maxLines } = {}) =>
      readBoundedBlobText(blob, { maxBytes, maxLines }),
    stream: async () => blob.stream(),
    readRange: async (range) => {
      validateByteRange(range)
      const { start, end } = range
      validateKnownByteRangeStart(start, blob.size)
      const rangeBlob = blob.slice(start, end + 1)
      return {
        buffer: await rangeBlob.arrayBuffer(),
        contentRange: {
          start,
          end: Math.min(end, blob.size - 1),
          total: blob.size,
        },
        isComplete: end >= blob.size - 1,
      }
    },
  })
}

function createTextResource(
  source: TextSource,
  descriptor: ViewerDescriptor,
  keys: ViewerResourceKeys
): ViewerResource {
  return resourceBase(source, descriptor, keys, {
    getDirectLoad: () => ({ kind: "none" }),
    getOriginalDownload: () =>
      createTextDownloadAction({
        id: "download-original",
        label: "Download",
        text: source.text,
        fileName: descriptor.fileName,
        mimeType: descriptor.mimeType,
      }),
    getInlineText: () => source.text,
    getBlob: () => null,
    readBlob: async () =>
      new Blob([source.text], {
        type: descriptor.mimeType ?? "text/plain;charset=utf-8",
      }),
    readArrayBuffer: async () => new TextEncoder().encode(source.text).buffer,
    readText: async ({ maxBytes, maxLines } = {}) =>
      readBoundedInlineText(source.text, { maxBytes, maxLines }),
    stream: async () => new Blob([source.text]).stream(),
    readRange: async (range) => {
      validateByteRange(range)
      const { start, end } = range
      const buffer = new TextEncoder().encode(source.text)
      validateKnownByteRangeStart(start, buffer.byteLength)
      const slice = buffer.slice(start, end + 1)
      return {
        buffer: slice.buffer,
        contentRange: {
          start,
          end: Math.min(end, buffer.byteLength - 1),
          total: buffer.byteLength,
        },
        isComplete: end >= buffer.byteLength - 1,
      }
    },
  })
}

function resourceBase(
  source: ViewerSource,
  descriptor: ViewerDescriptor,
  keys: ViewerResourceKeys,
  methods: Pick<
    ViewerResource,
    | "getDirectLoad"
    | "getOriginalDownload"
    | "getInlineText"
    | "getBlob"
    | "readBlob"
    | "readArrayBuffer"
    | "readText"
    | "stream"
    | "readRange"
  >
): ViewerResource {
  return Object.freeze({
    descriptor,
    sourceKind: source.kind,
    keys,
    identityKey: descriptor.identityKey,
    fileName: descriptor.fileName,
    mimeType: descriptor.mimeType,
    ...methods,
  })
}

async function fetchResource(
  input: RequestInfo | URL,
  init?: RequestInit
): Promise<Response> {
  let response: Response
  try {
    response = await fetch(input, init)
  } catch (error) {
    if (isAbortError(error)) {
      throw new ResourceError({
        kind: "aborted",
        message: "Loading was cancelled.",
        cause: error,
      })
    }
    throw new ResourceError({
      kind: "fetch_failed",
      message: "Could not fetch this resource.",
      cause: error,
    })
  }

  if (!response.ok && response.status !== 206) {
    throw new ResourceError({
      kind: "http_error",
      message: `Failed to load resource: ${response.status}`,
      status: response.status,
    })
  }

  return response
}

async function readBoundedResponseText(
  response: Response,
  bounds: { maxBytes?: number; maxLines?: number }
) {
  if (response.status === 206) {
    throw new ResourceError({
      kind: "partial_content",
      message: "Full text response returned partial content.",
      status: response.status,
    })
  }

  const maxBytes = bounds.maxBytes
  const contentLength = response.headers.get("content-length")
  const contentByteLength = contentLength ? Number(contentLength) : null
  if (
    maxBytes != null &&
    contentByteLength != null &&
    Number.isFinite(contentByteLength) &&
    contentByteLength > maxBytes
  ) {
    throw tooLarge("bytes")
  }

  const body = response.body
  if (!body) {
    const buffer = await response.arrayBuffer()
    if (maxBytes != null && buffer.byteLength > maxBytes) {
      throw tooLarge("bytes")
    }
    return readBoundedInlineText(new TextDecoder().decode(buffer), bounds)
  }

  const reader = body.getReader()
  const decoder = new TextDecoder()
  const lineLimitTracker = createLineLimitTracker(bounds.maxLines)
  let receivedBytes = 0
  let text = ""

  while (true) {
    const { done, value } = await reader.read()
    if (done) break
    receivedBytes += value.byteLength
    if (maxBytes != null && receivedBytes > maxBytes) {
      await reader.cancel()
      throw tooLarge("bytes")
    }
    const chunkText = decoder.decode(value, { stream: true })
    try {
      lineLimitTracker.push(chunkText)
    } catch (error) {
      await reader.cancel()
      throw error
    }
    text += chunkText
  }

  const finalText = decoder.decode()
  lineLimitTracker.push(finalText)
  text += finalText
  return readBoundedInlineText(text, bounds)
}

async function readBoundedBlobText(
  blob: Blob,
  bounds: { maxBytes?: number; maxLines?: number }
) {
  if (bounds.maxBytes != null && blob.size > bounds.maxBytes) {
    throw tooLarge("bytes")
  }
  return readBoundedInlineText(await blob.text(), bounds)
}

function readBoundedInlineText(
  text: string,
  { maxBytes, maxLines }: { maxBytes?: number; maxLines?: number }
) {
  if (
    maxBytes != null &&
    new TextEncoder().encode(text).byteLength > maxBytes
  ) {
    throw tooLarge("bytes")
  }
  if (
    maxLines != null &&
    text.split(TEXT_LINE_BREAK_PATTERN).length > maxLines
  ) {
    throw tooLarge("lines")
  }
  return text
}

function tooLarge(reason: ResourceTooLargeReason) {
  return new ResourceError({
    kind: "too_large",
    tooLargeReason: reason,
    message: `Resource exceeds ${reason} limit.`,
  })
}

function validateByteRange({ start, end }: ByteRange) {
  if (
    !Number.isSafeInteger(start) ||
    !Number.isSafeInteger(end) ||
    start < 0 ||
    end < start
  ) {
    throw new ResourceError({
      kind: "invalid_range",
      message: "Byte range must use non-negative integer bounds.",
    })
  }
}

function validateKnownByteRangeStart(start: number, total: number) {
  if (start > 0 && start >= total) {
    throw new ResourceError({
      kind: "invalid_range",
      message: "Byte range starts past the available resource.",
    })
  }
}

function isByteRangeComplete({
  bufferLength,
  contentRange,
  requestedLength,
  status,
}: {
  bufferLength: number
  contentRange: ByteRangeResult["contentRange"]
  requestedLength: number
  status: number
}) {
  if (status === 200) return true
  if (contentRange?.total != null) {
    if (contentRange.total <= 0) return true
    return contentRange.end >= contentRange.total - 1
  }
  return bufferLength < requestedLength
}

function createLineLimitTracker(maxLines: number | undefined) {
  let lineCount = 1
  let previousWasCR = false

  return {
    push(text: string) {
      if (maxLines == null || text.length === 0) return

      for (const character of text) {
        if (previousWasCR) {
          previousWasCR = false
          if (character === "\n") continue
        }

        if (character === "\r") {
          lineCount += 1
          previousWasCR = true
        } else if (character === "\n") {
          lineCount += 1
        }

        if (lineCount > maxLines) {
          throw tooLarge("lines")
        }
      }
    },
  }
}

function parseContentRange(value: string | null) {
  if (!value) return undefined
  const match = value.match(/bytes\s+(\d+)-(\d+)\/(\d+|\*)/i)
  if (!match) return undefined
  return {
    start: Number(match[1]),
    end: Number(match[2]),
    total: match[3] === "*" ? null : Number(match[3]),
  }
}
